let lang = 'en'
try { lang = localStorage.getItem('iam-lang') || (navigator.language || '').startsWith('es') && 'es' || 'en' } catch {}
const subs = []
export const t = k => (D[k] ? D[k][lang === 'es' ? 1 : 0] : k)
export const getLang = () => lang
export function setLang(l) {
  lang = l
  try { localStorage.setItem('iam-lang', l) } catch {}
  document.documentElement.lang = l
  subs.forEach(f => f())
}
export const onLang = f => subs.push(f)
